'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies } = require('./src/semver');

// Backtracking: a@2 needs c@2, b needs c@1 -> must fall back to a@1.
assert.deepEqual(resolve({
  a: { '2.0.0': { c: '2.0.0' }, '1.0.0': { c: '1.0.0' } },
  b: { '1.0.0': { c: '1.0.0' } },
  c: { '1.0.0': {}, '2.0.0': {} },
}, { a: '*', b: '*' }), { a: '1.0.0', b: '1.0.0', c: '1.0.0' });

// Undo of discarded choice's constraints: x@2 adds y<2 then fails on z; x@1 must not keep y<2.
assert.deepEqual(resolve({
  x: { '2.0.0': { y: '<2.0.0', z: '9.0.0' }, '1.0.0': {} },
  y: { '1.0.0': {}, '2.0.0': {} },
  z: { '1.0.0': {} },
}, { x: '*', y: '*' }), { x: '1.0.0', y: '2.0.0' });

// Cycle.
assert.deepEqual(resolve({
  p: { '1.0.0': { q: '^1.0.0' } },
  q: { '1.2.0': { p: '1.0.0' } },
}, { p: '*' }), { p: '1.0.0', q: '1.2.0' });

// Long chain, final link unsatisfiable on newest -> deep backtrack.
const N = 20000;
const reg = Object.create(null);
for (let i = 0; i < N; i += 1) reg['n' + i] = { '1.0.0': i + 1 < N ? { ['n' + (i + 1)]: '*' } : {} };
const r = resolve(reg, { n0: '*' });
assert.equal(Object.keys(r).length, N);

// No solution and missing package.
assert.equal(resolve({ a: { '1.0.0': { b: '2.0.0' } }, b: { '1.0.0': {} } }, { a: '*' }), null);
assert.equal(resolve({}, { ghost: '*' }), null);
assert.deepEqual(resolve({}, {}), {});

// Eager validation of unreachable entries.
assert.throws(() => resolve({ u: { '01.0.0': {} } }, {}), TypeError);
assert.throws(() => resolve({ u: { '1.0.0': { v: 'bogus' } } }, {}), TypeError);

// Caret zero-major rules.
assert.equal(satisfies('0.3.9', '^0.3.1'), true);
assert.equal(satisfies('0.4.0', '^0.3.1'), false);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);
assert.equal(satisfies('1.9.0', '^1.2.0'), true);
